insert into public.questions(id,topic,kind,prompt,choices,explanation,asset_paths) select id,topic,type,prompt,options,explanation,assets from jsonb_to_recordset($data$[{"id": 1, "topic": 0, "type": "ox", "prompt": "사회의 모습은 끊임없이 변한다.", "options": ["O", "X"], "explanation": "사회에는 사라지거나 새롭게 생기는 모습이 있어요.", "assets": []}, {"id": 2, "topic": 0, "type": "ox", "prompt": "사회가 변해도 예전에 없던 모습은 생기지 않는다.", "options": ["X", "O"], "explanation": "새로운 생활 모습이 생기기도 해요.", "assets": []}, {"id": 3, "topic": 0, "type": "choice", "prompt": "다른 나라와의 무엇이 사회 변화의 원인이 될까요?", "options": ["교류", "단절", "고립", "휴식"], "explanation": "다른 나라와 교류하면서 사회가 변화해요.", "assets": []}, {"id": 4, "topic": 0, "type": "situation", "prompt": "어린이가 줄어 초등학교가 문을 닫는 일을 무엇이라고 할까요?", "options": ["폐교", "입학", "개학", "졸업"], "explanation": "학생 수 감소로 문을 닫는 학교가 생겨요.", "assets": []}, {"id": 5, "topic": 1, "type": "choice", "prompt": "태어나는 아이의 수가 줄어 출산율이 감소하는 현상은?", "options": ["저출산", "고령화", "세계화", "지능정보화"], "explanation": "저출산은 태어나는 아이의 수가 줄어드는 현상이에요.", "assets": []}, {"id": 6, "topic": 1, "type": "ox", "prompt": "저출산으로 가족 구성원 수가 줄어들 수 있다.", "options": ["O", "X"], "explanation": "학습지에서는 가족 구성원 수가 줄어드는 모습을 설명해요.", "assets": []}, {"id": 7, "topic": 1, "type": "choice", "prompt": "저출산으로 초등학생 수는 어떻게 달라질까요?", "options": ["줄어든다", "늘어난다", "항상 같다", "갑자기 두 배가 된다"], "explanation": "태어나는 아이가 줄어 학생 수도 줄어들어요.", "assets": []}, {"id": 8, "topic": 1, "type": "choice", "prompt": "저출산이 계속되면 일할 수 있는 사람 수는 어떻게 될 것으로 예상할까요?", "options": ["줄어든다", "늘어난다", "항상 같다", "모두 사라진다"], "explanation": "일할 수 있는 사람의 수가 줄어들 것으로 예상해요.", "assets": []}, {"id": 9, "topic": 1, "type": "picture", "prompt": "그림처럼 어린아이를 안전하게 돌보는 시설은?", "options": ["보육 시설", "노인 복지관", "영화관", "박물관"], "explanation": "안전하고 쾌적한 보육 시설은 아이를 키우는 데 도움을 줘요.", "assets": ["images/d7f3e9e992444a58.svg", "images/00cc8a68268e4e20.svg", null, null]}, {"id": 10, "topic": 1, "type": "situation", "prompt": "부모가 자녀를 돌볼 시간을 마련하려면 어떤 지원이 좋을까요?", "options": ["일정 기간 일을 쉴 수 있는 제도", "쉬는 시간 없애기", "보육 시설 줄이기", "돌봄 지원 없애기"], "explanation": "부모가 자녀를 키우기 위해 일정 기간 일을 쉴 수 있도록 지원해요.", "assets": []}, {"id": 11, "topic": 2, "type": "choice", "prompt": "전체 사람 수에서 노인의 비율이 높아지는 현상은?", "options": ["고령화", "저출산", "세계화", "지능정보화"], "explanation": "고령화는 전체 인구 중 노인의 비율이 높아지는 현상이에요.", "assets": []}, {"id": 12, "topic": 2, "type": "ox", "prompt": "의학 기술이 발달하면 사람들이 더 오래 살 수 있다.", "options": ["O", "X"], "explanation": "의학 기술의 발달과 깨끗한 환경은 평균 수명 증가에 도움을 줘요.", "assets": []}, {"id": 13, "topic": 2, "type": "picture", "prompt": "그림처럼 노인의 건강과 여가를 돕는 시설은?", "options": ["노인 복지관", "초등학교", "보육 시설", "영화관"], "explanation": "노인 복지관은 노인을 위한 시설이에요.", "assets": ["images/00cc8a68268e4e20.svg", null, "images/d7f3e9e992444a58.svg", null]}, {"id": 14, "topic": 2, "type": "situation", "prompt": "고령화에 대비해 노인에게 제공하면 좋은 것은?", "options": ["알맞은 일자리", "배움의 기회 없애기", "복지 시설 줄이기", "건강 지원 중단"], "explanation": "노인에게 알맞은 일자리를 제공하는 노력이 필요해요.", "assets": []}, {"id": 15, "topic": 2, "type": "choice", "prompt": "노인의 건강하고 안정적인 생활을 돕는 제도는?", "options": ["복지 제도", "입학 제도", "수출 제도", "출입국 제도"], "explanation": "다양한 복지 제도로 노인의 생활을 지원해요.", "assets": []}, {"id": 16, "topic": 2, "type": "ox", "prompt": "노인에게 배움의 기회를 제공하는 프로그램도 운영된다.", "options": ["O", "X"], "explanation": "고령화에 따라 노인을 위한 배움의 기회가 마련돼요.", "assets": []}, {"id": 17, "topic": 3, "type": "choice", "prompt": "사람처럼 정보를 익히고 처리하는 컴퓨터 시스템은?", "options": ["인공지능", "세계화", "고령화", "저출산"], "explanation": "인공지능은 많은 정보를 처리하는 데 활용돼요.", "assets": []}, {"id": 18, "topic": 3, "type": "choice", "prompt": "인공지능을 활용한 기술이 사회 전반에 영향을 미치는 현상은?", "options": ["지능정보화", "세계화", "저출산", "고령화"], "explanation": "인공지능 기술이 생활 곳곳에 영향을 미치는 현상이에요.", "assets": []}, {"id": 19, "topic": 3, "type": "image", "prompt": "인공지능 기술을 활용한 농사 모습을 고르세요.", "options": ["스마트 팜", "전통 혼례", "윷놀이", "연날리기"], "explanation": "스마트 팜은 기술을 활용해 편리하게 농사짓는 사례예요.", "assets": ["images/d3e97ca9ef254ec4.svg", "images/b100685d114f44b0.svg", "images/af4f943252ce4112.svg", "images/afd2b2a4968343f4.svg"]}, {"id": 20, "topic": 3, "type": "picture", "prompt": "그림처럼 사람 대신 집을 청소하는 기기는?", "options": ["청소 로봇", "선풍기", "냉장고", "전등"], "explanation": "청소 로봇은 과학 기술로 달라진 생활의 예예요.", "assets": ["images/dac35f39cd4e457e.svg", null, null, null]}, {"id": 21, "topic": 3, "type": "situation", "prompt": "인터넷에서 다른 사람의 개인 정보를 함부로 사용하는 범죄는?", "options": ["사이버 범죄", "전통 놀이", "세계화", "보육 활동"], "explanation": "다른 사람의 개인 정보를 허락 없이 사용하는 것은 사이버 범죄예요.", "assets": []}, {"id": 22, "topic": 3, "type": "choice", "prompt": "스마트폰을 지나치게 이용하여 문제가 되는 상태는?", "options": ["과의존", "교류", "복지", "수확"], "explanation": "인터넷이나 스마트폰의 과도한 이용을 과의존이라고 해요.", "assets": []}, {"id": 23, "topic": 3, "type": "ox", "prompt": "인공지능이 만들어 낸 정보는 언제나 사실이다.", "options": ["X", "O"], "explanation": "인공지능이 거짓 정보를 만들기도 해요.", "assets": []}, {"id": 24, "topic": 3, "type": "situation", "prompt": "인공지능으로 직업 환경이 달라질 때 필요한 노력은?", "options": ["달라질 직업 환경에 대비하는 교육", "모든 교육 중단", "거짓 정보 퍼뜨리기", "인터넷 과의존 늘리기"], "explanation": "변화에 대응할 수 있도록 교육을 해요.", "assets": []}, {"id": 25, "topic": 4, "type": "choice", "prompt": "여러 나라가 교류하며 세계가 하나로 연결되는 현상은?", "options": ["세계화", "고령화", "저출산", "과의존"], "explanation": "세계화는 여러 나라가 다양한 분야에서 교류하는 현상이에요.", "assets": []}, {"id": 26, "topic": 4, "type": "ox", "prompt": "세계화로 다른 나라의 음식을 구입할 수 있다.", "options": ["O", "X"], "explanation": "다른 나라의 식품이나 물건을 구입할 수 있어요.", "assets": []}, {"id": 27, "topic": 4, "type": "situation", "prompt": "우리나라 회사가 여러 나라에 진출하는 것은 어떤 변화와 관련 있을까요?", "options": ["세계화", "저출산", "고령화", "품앗이"], "explanation": "세계화로 우리나라 회사가 세계 곳곳에 진출해요.", "assets": []}, {"id": 28, "topic": 4, "type": "ox", "prompt": "세계화로 전통적인 생활 양식이 약해질 수 있다.", "options": ["O", "X"], "explanation": "생활 양식이 비슷해지면서 전통이 약해질 수 있어요.", "assets": []}, {"id": 29, "topic": 4, "type": "situation", "prompt": "다른 나라의 생활 양식을 받아들일 때 알맞은 태도는?", "options": ["장단점을 따져 받아들인다", "무조건 따라 한다", "모두 거부한다", "우리 전통을 모두 버린다"], "explanation": "장점과 단점을 살펴 받아들이는 태도가 필요해요.", "assets": []}, {"id": 30, "topic": 4, "type": "choice", "prompt": "나라 사이를 이동하는 사람이 많아지면 빠르게 퍼질 수 있는 것은?", "options": ["감염병", "보육 시설", "전통 놀이", "복지관"], "explanation": "감염병은 여러 나라가 함께 해결하려 노력해야 해요.", "assets": []}, {"id": 31, "topic": 5, "type": "choice", "prompt": "옛날부터 되풀이되어 전해 오는 생활 습관과 모습은?", "options": ["풍습", "세계화", "고령화", "과의존"], "explanation": "풍습은 오래전부터 전해 오는 생활 습관과 모습이에요.", "assets": []}, {"id": 32, "topic": 5, "type": "choice", "prompt": "해마다 일정한 때에 되풀이하는 풍습은?", "options": ["세시 풍속", "지능정보화", "저출산", "관례"], "explanation": "명절이나 절기에 하는 일, 음식, 놀이 등이 있어요.", "assets": []}, {"id": 33, "topic": 5, "type": "ox", "prompt": "생일에 미역국을 먹는 것은 풍습의 예이다.", "options": ["O", "X"], "explanation": "생일날 미역국을 먹는 것도 풍습이에요.", "assets": []}, {"id": 34, "topic": 5, "type": "ox", "prompt": "옛날 풍습에는 서로 돕고 기쁨과 슬픔을 나누는 마음이 담겨 있다.", "options": ["O", "X"], "explanation": "중요한 일이 있을 때 서로 축하하거나 위로했어요.", "assets": []}, {"id": 35, "topic": 6, "type": "choice", "prompt": "많은 일손이 필요한 농사일을 함께하려고 만든 마을 공동 조직은?", "options": ["두레", "품앗이", "혼례", "관례"], "explanation": "두레는 모내기나 벼 베기 등을 함께하는 마을 공동 조직이에요.", "assets": []}, {"id": 36, "topic": 6, "type": "situation", "prompt": "김장할 때 이웃끼리 돌아가면서 일손을 돕는 풍습은?", "options": ["품앗이", "두레", "회갑", "장례"], "explanation": "품앗이는 일손이 모자란 일을 서로 돌아가며 돕는 일이에요.", "assets": []}, {"id": 37, "topic": 6, "type": "picture", "prompt": "그림처럼 마을 공동 조직이 함께 벼를 베는 모습은?", "options": ["두레", "혼례", "관례", "백일잔치"], "explanation": "많은 일손이 필요한 농사일을 마을 공동 조직이 함께했어요.", "assets": ["images/3f6267cddbc546f6.svg", null, null, null]}, {"id": 38, "topic": 6, "type": "situation", "prompt": "이웃집 지붕을 얹는 일을 돕고 다음에는 우리 집 일을 도움받는 풍습은?", "options": ["품앗이", "두레", "회갑", "첫돌"], "explanation": "서로 돌아가면서 일을 돕는 것이 품앗이예요.", "assets": []}, {"id": 39, "topic": 7, "type": "picture", "prompt": "옛날 아기가 태어나면 대문에 쳤던 것은?", "options": ["금줄", "복조리", "부채", "연"], "explanation": "산모와 아기의 건강을 바라며 금줄을 쳤어요.", "assets": ["images/8727546e56164d89.svg", null, null, null]}, {"id": 40, "topic": 7, "type": "choice", "prompt": "아기가 태어난 지 100일이 된 것을 축하하는 풍습은?", "options": ["백일잔치", "첫돌", "회갑", "관례"], "explanation": "백일에는 아기가 태어난 지 100일을 축하했어요.", "assets": []}, {"id": 41, "topic": 7, "t